import { smooth } from "./rig.js";

// One clock drives the broken tubes, page wash, and light on the 3D objects.
const FAULTS = [[0, 0], [.11, 1], [.2, 0], [.32, 1], [.43, 0], [.57, 1], [.66, .3], [.74, 0], [.87, 1], [.94, .3]];
function circuit(time, duration, offset = 0) {
  const progress = ((time + offset) % duration) / duration;
  let power = 0;
  for (const [start, value] of FAULTS) {
    if (progress < start) break;
    power = value;
  }
  return power;
}

export function createNeonLighting() {
  let time = 0;
  const light = { level: 0, power: 0, faultA: 0, faultB: 0 };
  return {
    update(story, dt) {
      const active = ["sleep", "neon", "wake"].includes(story.phase);
      time = active ? time + dt : 0;
      light.level = story.phase === "sleep" ? smooth(story.time / .3)
        : story.phase === "neon" ? 1
          : story.phase === "wake" ? 1 - smooth(story.time / .55) : 0;
      light.faultA = circuit(time, 4.6);
      light.faultB = circuit(time, 5.3, .9);
      light.power = light.level * (.58 + .25 * light.faultA + .17 * light.faultB);
      return light;
    },
  };
}
