import {
  DirectionalLight,
  HemisphereLight,
  PCFShadowMap,
  PerspectiveCamera,
  PointLight,
  Scene,
  SpotLight,
  Vector3,
  WebGLRenderer,
} from "three";
import { Kit, buildCharacter, buildWorld } from "./models.js";
import { loadPortrait } from "./portrait.js";
import { createHaze } from "./haze.js";
import { createRoutine } from "./routine.js";
import { claimGreeting, createGreeting, greetingLine } from "./activity.js";
import { createCoffeeStory } from "./coffeeStory.js";
import { createCoffeeMotion } from "./coffeeMotion.js";
import { createNeonLighting } from "./neonLighting.js";
import { LAMP_TIMING, createLampMotion } from "./lampMotion.js";
import { createMeterDisplay, createPrint, createScope, createStationDisplay, createTerminal } from "./screens.js";
import { Spring, clamp, damp, placeSegment, random, solveLimb, wrapAngle } from "./rig.js";

const THEMES = {
  light: { sky: "#fdfaf2", ground: "#c9c2ae", hemi: 1.8, sun: "#fff2dd", sunIntensity: 2.3, fill: 0.45, glow: 0.3, shadow: 0.16, steam: "#a9b4b3", smoke: "#7a868d", rug: "#d5dacb" },
  dark: { sky: "#8ea4bd", ground: "#35322d", hemi: 0.85, sun: "#b4c6e2", sunIntensity: 1.0, fill: 0.5, glow: 1.5, shadow: 0.36, steam: "#e8efe9", smoke: "#f2efe8", rug: "#8a9486" },
};

// The camera looks over his left shoulder; the introduction faces this fixed view.
export const VIEW = { target: [0, 0.5, 0.3], azimuth: 2.36, elevation: 0.42, distance: 4.8, fov: 26, aspect: 1.15 };

const UP = new Vector3(0, 1, 0);
// Seconds to put the tools down after the support key is left without a click.
const NAP_PUT_DOWN = 0.32;

export async function createHeroDesk(canvas, options = {}) {
  await loadPortrait(options.portraitUrl);
  const { onGreeting, onActivity, onCoffee, onLighting } = options;
  const view = { ...VIEW, ...options.view };
  const renderer = new WebGLRenderer({ canvas, antialias: true, alpha: true, preserveDrawingBuffer: Boolean(options.preserveDrawingBuffer) });
  renderer.setClearColor(0x000000, 0);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = PCFShadowMap;

  const scene = new Scene();
  const camera = new PerspectiveCamera(view.fov, view.aspect, 0.1, 40);
  const focus = new Vector3(...view.target);
  let fittedFov = view.fov;
  camera.position.set(
    focus.x - Math.sin(view.azimuth) * Math.cos(view.elevation) * view.distance,
    focus.y + Math.sin(view.elevation) * view.distance,
    focus.z - Math.cos(view.azimuth) * Math.cos(view.elevation) * view.distance,
  );
  camera.lookAt(focus);

  const kit = new Kit(11);
  const screens = {
    terminal: createTerminal(),
    scope: createScope(),
    meter: createMeterDisplay(),
    station: createStationDisplay(),
    print: createPrint(),
  };
  const world = buildWorld(kit, screens);
  const rig = buildCharacter(kit, screens.print.texture);
  // Eyes and brows move a little around where the face model put them.
  const face = { eyes: rig.eyes.map((eye) => eye.position.clone()), brows: rig.brows.map((brow) => brow.position.y) };
  rig.root.position.copy(world.chairHome);
  scene.add(world.group, rig.root, rig.limbs);

  const hemi = new HemisphereLight();
  const sun = new DirectionalLight();
  sun.position.set(-2.2, 3.9, 1.5);
  sun.target.position.set(0.1, 0.4, 0.25);
  sun.castShadow = true;
  sun.shadow.mapSize.set(1024, 1024);
  Object.assign(sun.shadow.camera, { left: -1.6, right: 1.6, top: 1.6, bottom: -1.6, near: 1, far: 9 });
  sun.shadow.camera.updateProjectionMatrix();
  sun.shadow.bias = -0.0004;
  sun.shadow.normalBias = 0.015;
  sun.shadow.radius = 3;
  const fill = new DirectionalLight("#dfe8ff");
  fill.position.set(2.6, 1.8, 2.2);
  const glow = new PointLight("#9fe0a8", 0, 1.7, 2);
  glow.position.copy(world.focus.screen).add(new Vector3(0, 0, 0.14));
  scene.add(hemi, sun, sun.target, fill, glow);
  const lampLight = new SpotLight("#ffdda4", 0, 2.4, Math.PI / 5, 0.65, 2);
  lampLight.position.copy(world.lamp.source);
  lampLight.target.position.copy(world.lamp.target);
  lampLight.angle = Math.PI / 7;
  lampLight.castShadow = true;
  lampLight.shadow.mapSize.set(512, 512);
  lampLight.shadow.bias = -0.0002;
  lampLight.shadow.normalBias = 0.006;
  scene.add(lampLight, lampLight.target);
  // Off-camera, on the sign's side of the composition. These illuminate the
  // actual materials, including the shirt, skin, wood, and equipment edges.
  const neon = new PointLight("#ff397a", 0, 6, 2);
  neon.position.set(-1.55, 1.8, -.7);
  const neonBounce = new PointLight("#ed527e", 0, 4, 2);
  neonBounce.position.set(-.8, .95, 1.2);
  scene.add(neon, neonBounce);

  const rand = random(5);
  const haze = createHaze(160, rand);
  scene.add(haze.points);
  // Only the hot iron emits a thin wisp; the empty cup never steams.
  const vents = [
    { origin: world.steam, every: 0.35, clock: 0, life: 1.8, rise: 0.09, start: 0.008, grow: 0.025, peak: 0.4, spread: 0.004 },
  ];
  // A slight draft carries the smoke back past his head, where it stays in view.
  const fumes = { life: 2.4, rise: 0.3, start: 0.02, grow: 0.09, peak: 0.75, shade: 1, spread: 0.008, wind: [-0.12, -0.16] };
  let smokeClock = 0;
  const routine = createRoutine({ bench: world.bench, terminal: screens.terminal, screen: world.focus.screen, onActivity });
  const greeting = createGreeting({ claim: () => options.authoring || claimGreeting() });
  const story = createCoffeeStory();
  const coffeeMotion = createCoffeeMotion({ world });
  const lampMotion = createLampMotion({ world });
  const neonLighting = createNeonLighting();
  let theme = THEMES[options.theme] || THEMES.light;
  let lighting = { level: 0, power: 0, faultA: 0, faultB: 0 };
  let lightingSignature = "";
  let lampOn = false;
  let lampTarget = false;
  let lampRequested = false;
  let lampAction = null;
  let dozeAt = Infinity;
  let storySignature = "";
  let greetingStage = "";

  const state = {
    time: 0,
    forced: null,
    waiting: true,
    chair: new Spring(0, 26, 8),
    chairTarget: 0,
    roll: new Spring(0, 30, 11),
    feet: 0,
    headYaw: 0,
    headPitch: -0.2,
    twist: 0,
    lean: 0.17,
    typing: 1,
    wave: 0,
    smile: 0.2,
    brow: 0,
    blinkAt: 2.5,
    blinkUntil: 0,
    cabled: false,
    hold: [0, 0],
    wrists: [new Vector3(), new Vector3()],
    dirs: [new Vector3(0, 0, -1), new Vector3(0, 0, -1)],
    reach: [new Vector3(), new Vector3()],
    point: [new Vector3(0, 0, -1), new Vector3(0, 0, -1)],
  };
  const typing = { next: 0, burstEnd: 0, pauseEnd: 0, hand: 1, taps: [0, 0], offsets: [new Vector3(), new Vector3()] };

  const v = {
    look: new Vector3(), neck: new Vector3(), right: new Vector3(), shoulder: new Vector3(), elbow: new Vector3(),
    wrist: new Vector3(), hand: new Vector3(), rest: new Vector3(), wave: new Vector3(), pole: new Vector3(),
    wavePole: new Vector3(), dir: new Vector3(), fingers: new Vector3(), hip: new Vector3(), knee: new Vector3(),
    ankle: new Vector3(), foot: new Vector3(), feetRight: new Vector3(), anchor: new Vector3(),
  };

  function publishCoffee() {
    const phase = story.phase;
    const message = phase === "thanks" ? "Your support keeps me building. ♥" : "";
    const signature = `${phase}:${message}:${story.attention}`;
    if (signature === storySignature) return;
    storySignature = signature;
    onCoffee?.(phase ? { phase, message, attention: story.attention, covered: story.covered, anchor: anchor() } : null);
    if (phase) onActivity?.(`coffee-${phase}`);
  }

  function cancelStory() {
    const needsReset = story.active || story.pending;
    story.cancel();
    if (!needsReset) return;
    rig.actor.position.set(0, 0, 0);
    rig.actor.rotation.y = 0;
    state.hold.fill(0);
    update(0);
    camera.fov = fittedFov;
    camera.lookAt(focus);
    camera.updateProjectionMatrix();
    publishCoffee();
  }

  function chooseMode() {
    if (state.forced) return state.forced;
    return greeting.active ? "engaged" : "work";
  }

  function workLook(out) {
    return out.copy(world.focus.screen);
  }

  function press(hand, x, z) {
    typing.taps[hand] = 1;
    typing.offsets[hand].set(x, 0, z);
  }

  function updateTyping(active) {
    if (!active) return;
    const now = state.time;
    if (now > typing.burstEnd) {
      if (now > typing.pauseEnd) {
        typing.burstEnd = now + 1.4 + rand() * 2.6;
        typing.pauseEnd = typing.burstEnd + 0.5 + rand() * 1.5;
      }
      return;
    }
    if (now < typing.next) return;
    const hand = rand() < 0.68 ? 1 - typing.hand : typing.hand;
    typing.hand = hand;
    press(hand, (rand() - 0.5) * 0.07, (rand() - 0.5) * 0.035);
    typing.next = now + 0.08 + rand() * 0.1;
    screens.terminal.typeCode();
  }

  function anchor() {
    rig.head.getWorldPosition(v.anchor);
    v.anchor.y += 0.34;
    v.anchor.project(camera);
    return { x: (v.anchor.x + 1) / 2, y: (1 - v.anchor.y) / 2 };
  }

  function updateHaze(dt, source) {
    for (const vent of vents) {
      vent.clock += dt;
      for (; vent.clock > vent.every; vent.clock -= vent.every) haze.emit(vent.origin, vent);
    }
    smokeClock = source ? smokeClock + dt : 0;
    for (; source && smokeClock > 0.04; smokeClock -= 0.04) haze.emit(source, fumes);
    haze.update(dt);
  }

  function update(dt) {
    state.time += dt;
    const now = state.time;
    // Touch screens cannot hover the coffee key, so he dozes off once on a timer.
    if (now >= dozeAt && !state.waiting) {
      dozeAt = Infinity;
      story.doze();
    }
    // Put tools down before the greeting, the lamp, or a coffee pause; a nap
    // the visitor just triggered should not keep them waiting.
    if ((greeting.pending || story.pending || lampRequested) && routine.active) routine.abort(story.pending ? NAP_PUT_DOWN : undefined);
    let bench = routine.update(dt, state.wrists, state.dirs);
    if (lampRequested && !routine.active && !greeting.active && !greeting.pending && !story.active && !story.pending && !lampAction) {
      lampMotion.begin(rig.actor, state.wrists, state.dirs);
      lampAction = { switched: false };
      lampRequested = false;
      onActivity?.("lamp");
    }
    if (lampAction) {
      bench = lampMotion.update(dt);
      if (lampMotion.time >= LAMP_TIMING.click && !lampAction.switched) { applyLamp(lampTarget); lampAction.switched = true; }
      if (lampMotion.time >= LAMP_TIMING.end) { lampAction = null; if (lampOn === lampTarget) lampRequested = false; }
    }
    // The nap happens at the desk. A nap asked for during the introduction ends
    // it early; he swivels back to the desk and dozes off once he faces it.
    if (story.pending && greeting.active) greeting.finish();
    const atDesk = Math.abs(state.chairTarget) < 1 && Math.abs(state.chair.value - state.chairTarget) < 0.3;
    if (story.pending && atDesk && !routine.active && !greeting.active && !lampAction) {
      if (story.startNap()) {
        coffeeMotion.begin(rig.root.position, state.chairTarget, { hands: state.wrists, dirs: state.dirs, lean: state.lean, look: v.look });
      }
    }
    story.advance(dt);
    lighting = neonLighting.update(story, dt);
    applyLighting();
    const storyPose = story.active ? coffeeMotion.update(story) : null;
    greeting.advance(dt, !routine.active && !story.active && !story.pending && !lampAction && !state.waiting);
    const mode = chooseMode();
    const hello = greeting.active ? greetingLine(greeting.time) : "";
    if (hello !== greetingStage) {
      greetingStage = hello;
      onGreeting?.(hello ? anchor() : null, hello);
      if (hello) onActivity?.("greeting");
    }
    if (storyPose) bench = storyPose;
    if (!routine.active && mode === "work" && !greeting.pending && !state.waiting && !state.forced && !story.active && !story.pending && !lampAction && !lampRequested) routine.start();

    // Aim from eye height so close things like a held board draw his gaze down.
    rig.head.getWorldPosition(v.neck);
    v.neck.y += 0.13;
    if (mode === "work" && bench) v.look.copy(bench.look);
    else if (mode === "work") workLook(v.look);
    else {
      v.look.copy(camera.position);
      v.look.y -= 0.6;
    }
    const dx = v.look.x - v.neck.x;
    const dy = v.look.y - v.neck.y;
    const dz = v.look.z - v.neck.z;
    const desiredYaw = Math.atan2(-dx, -dz);
    const desiredPitch = Math.atan2(dy, Math.hypot(dx, dz));

    // The head turns first; the chair makes up whatever the neck cannot.
    let chairTarget = 0.035 * Math.sin(now * 0.35);
    if (mode === "engaged") chairTarget = clamp(desiredYaw > -1.4 ? desiredYaw : desiredYaw + Math.PI * 2, -0.6, 2.7) * 0.86;
    if (bench) chairTarget = bench.chair;
    state.chairTarget = chairTarget;
    const chair = state.chair.update(chairTarget, dt);
    const roll = state.roll.update(bench ? bench.roll : mode === "engaged" ? 0.16 : 0, dt);
    const yaw = chair;
    rig.root.position.set(world.chairHome.x, 0, world.chairHome.z + roll);
    rig.swivel.rotation.y = chair;
    rig.actor.position.set(0, 0, 0);
    rig.actor.rotation.y = 0;
    state.feet = damp(state.feet, yaw, storyPose ? 9 : mode === "engaged" ? 5 : 3, dt);

    const lean = bench ? bench.lean : mode === "work" ? 0.17 : -0.03;
    state.lean = damp(state.lean, lean, 4, dt);
    const headYaw = clamp(wrapAngle(desiredYaw - yaw - state.twist), -1.15, 1.15);
    state.twist = damp(state.twist, headYaw * 0.25, 4, dt);
    state.headYaw = damp(state.headYaw, headYaw, mode === "work" ? 5 : 8, dt);
    state.headPitch = damp(state.headPitch, clamp(desiredPitch + state.lean, -0.55, 0.45), 7, dt);
    rig.spine.rotation.set(-state.lean, state.twist, 0);
    rig.spine.position.y = 0.585 + Math.sin(now * 1.7) * 0.003;
    rig.head.rotation.set(state.headPitch, state.headYaw, bench?.sleep ? -0.25 * bench.sleep : mode === "engaged" ? -0.07 : 0);

    if (now > state.blinkAt) {
      state.blinkUntil = now + 0.11;
      state.blinkAt = now + 2.4 + rand() * 3.2;
    }
    const eyeYaw = clamp(wrapAngle(desiredYaw - yaw - state.twist) - state.headYaw, -0.35, 0.35);
    const eyePitch = clamp(desiredPitch + state.lean - state.headPitch, -0.3, 0.3);
    rig.eyes.forEach((eye, i) => {
      eye.position.x = face.eyes[i].x + eyeYaw * 0.007;
      eye.position.y = face.eyes[i].y + eyePitch * 0.005;
      eye.scale.y = bench?.sleep > 0.75 || now < state.blinkUntil ? 0.05 : 1;
    });
    state.smile = damp(state.smile, mode === "engaged" ? 1 : bench ? bench.smile : 0.2, 5, dt);
    state.brow = damp(state.brow, mode === "engaged" ? 1 : 0, 6, dt);
    rig.mouth.grin.visible = state.smile > 0.6;
    rig.mouth.line.visible = !rig.mouth.grin.visible;
    rig.brows.forEach((brow, i) => { brow.position.y = face.brows[i] + state.brow * 0.005; });

    const typingTarget = mode === "work" && bench?.typing ? 1 : 0;
    state.typing = damp(state.typing, typingTarget, 6, dt);
    const waving = state.forced === "engaged" || (greeting.active && greeting.time > 0.8 && greeting.time < 3.2);
    state.wave = damp(state.wave, waving ? 1 : 0, 6, dt);
    updateTyping(!state.waiting && !state.forced && bench?.typing && state.typing > 0.85);

    rig.root.updateMatrixWorld(true);
    // Hands and carried things that move with him, placed now that the chair has turned.
    bench?.follow?.(rig);
    v.right.set(Math.cos(yaw), 0, -Math.sin(yaw));
    rig.arms.forEach((arm, i) => {
      typing.taps[i] = Math.max(0, typing.taps[i] - dt * 8);
      const tap = Math.sin(typing.taps[i] * Math.PI) * 0.016;
      v.hand.copy(world.focus.keys[i]).add(typing.offsets[i]);
      v.hand.y += 0.006 - tap;
      rig.actor.localToWorld(v.rest.set(arm.side * 0.12, 0.64, -0.2));
      v.hand.lerpVectors(v.rest, v.hand, state.typing);
      v.pole.set(arm.side * 0.45, 0.72, 0.25);
      // Keep elbows outside the torso as the forearms settle onto the desk.
      if (bench?.sleep) v.pole.lerp(v.wavePole.set(arm.side * 0.55, 0.77, -0.22), bench.sleep);
      if (i === 1 && state.wave > 0.001) {
        rig.actor.localToWorld(v.wave.set(0.26 + Math.sin(now * 9) * 0.045, 1.3, -0.1));
        v.hand.lerp(v.wave, state.wave);
        v.pole.lerp(v.wavePole.set(0.55, 0.85, 0.05), state.wave);
      }
      if (bench?.holding[i]) {
        state.reach[i].copy(bench.hands[i]);
        state.point[i].copy(bench.dirs[i]);
      }
      state.hold[i] = bench?.holding[i] ? 1 : damp(state.hold[i], 0, 7, dt);
      v.hand.lerp(state.reach[i], state.hold[i]);
      rig.actor.localToWorld(v.pole);
      rig.shoulders[i].getWorldPosition(v.shoulder);
      solveLimb(v.shoulder, v.hand, v.pole, arm.upperLength, arm.lowerLength, v.elbow, v.wrist);
      placeSegment(arm.upper, v.shoulder, v.elbow, v.right);
      placeSegment(arm.lower, v.elbow, v.wrist, v.right);
      v.dir.subVectors(v.wrist, v.elbow).normalize();
      v.dir.y -= 0.55 * state.typing + 0.15 * (1 - state.typing);
      if (i === 1) v.dir.lerp(UP, state.wave);
      v.dir.normalize().lerp(state.point[i], state.hold[i]).normalize();
      v.fingers.copy(v.wrist).addScaledVector(v.dir, 0.1);
      placeSegment(arm.hand, v.wrist, v.fingers, v.right);
      state.wrists[i].copy(v.wrist);
      state.dirs[i].copy(v.dir);
    });

    const sin = Math.sin(state.feet);
    const cos = Math.cos(state.feet);
    v.feetRight.set(cos, 0, -sin);
    rig.legs.forEach((leg, i) => {
      rig.hips[i].getWorldPosition(v.hip);
      const x = leg.side * 0.155;
      const z = -0.4;
      v.foot.set(rig.root.position.x + x * cos + z * sin, 0.09, rig.root.position.z - x * sin + z * cos);
      v.pole.set(v.hip.x - sin * 0.6, v.hip.y + 0.35, v.hip.z - cos * 0.6);
      solveLimb(v.hip, v.foot, v.pole, leg.upperLength, leg.lowerLength, v.knee, v.ankle);
      placeSegment(leg.thigh, v.hip, v.knee, v.feetRight);
      placeSegment(leg.shin, v.knee, v.ankle, v.feetRight);
      leg.foot.position.copy(v.ankle);
      leg.foot.rotation.set(0, state.feet, 0);
    });

    screens.terminal.update(now, dt);
    screens.scope.update(now);
    screens.meter.update(now);
    for (const led of world.leds) led.material.color.set(Math.sin(now * led.rate * Math.PI * 2) > 0 ? led.on : led.off);
    const { iron } = world.bench;
    iron.group.updateMatrixWorld();
    iron.group.localToWorld(world.steam.copy(iron.tip));
    if (bench || routine.active !== state.cabled) world.bench.cable.update(world.bench.stationJack, iron.group.localToWorld(v.anchor.copy(iron.end)), world.bench.top);
    state.cabled = routine.active;
    updateHaze(dt, bench?.smoke);
    publishCoffee();
  }

  function applyLamp(on) {
    lampOn = on;
    applyLighting();
    world.lamp.bulb.material.color.set(on ? "#f9df9c" : "#454f4b");
    world.lamp.toggle.rotation.x = on ? -0.18 : 0.18;
  }

  function applyLighting() {
    const { level, power, faultA, faultB } = lighting;
    hemi.intensity = theme.hemi * (1 - level * .72);
    sun.intensity = theme.sunIntensity * (1 - level * .88);
    fill.intensity = theme.fill * (1 - level * .65);
    glow.intensity = theme.glow * (1 - level * .96);
    lampLight.intensity = lampOn ? 2.4 * (1 - level * .72) : 0;
    neon.intensity = power * 6;
    neonBounce.intensity = power * 1.3;
    const signature = `${level.toFixed(3)}:${power.toFixed(3)}:${faultA}:${faultB}`;
    if (signature !== lightingSignature) {
      lightingSignature = signature;
      onLighting?.(lighting);
    }
  }

  function setTheme(name, animate = false) {
    theme = THEMES[name] || THEMES.light;
    sun.castShadow = true;
    world.floor.visible = true;
    hemi.color.set(theme.sky);
    hemi.groundColor.set(theme.ground);
    sun.color.set(theme.sun);
    applyLighting();
    world.floor.material.opacity = theme.shadow;
    world.rug.color.set(theme.rug);
    haze.colors(theme.steam, theme.smoke);
    lampTarget = name === "dark";
    if (animate && !state.waiting && lampTarget !== lampOn) lampRequested = true;
    else { lampRequested = false; lampAction = null; applyLamp(lampTarget); }
  }

  function resize(width, height, pixelRatio = Math.min(window.devicePixelRatio || 1, 2)) {
    if (!width || !height) return;
    renderer.setPixelRatio(pixelRatio);
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    const fit = Math.max(1, view.aspect / camera.aspect);
    fittedFov = (2 * Math.atan(Math.tan((view.fov * Math.PI) / 360) * fit) * 180) / Math.PI;
    camera.fov = fittedFov;
    camera.updateProjectionMatrix();
    haze.scale((height * pixelRatio) / (2 * Math.tan((camera.fov * Math.PI) / 360)));
  }

  let last = 0;
  let running = false;
  const frame = (time) => {
    const dt = Math.min((time - last) / 1000, 0.1);
    last = time;
    if (dt > 0) update(dt);
    renderer.render(scene, camera);
  };

  screens.terminal.showSchematic();

  // Settle into the working pose so the first frame matches the placeholder image.
  for (let i = 0; i < 120; i += 1) update(1 / 60);
  setTheme(options.theme);
  document.fonts?.load(`20px "JetBrains Mono"`).then(() => {
    Object.values(screens).forEach((screen) => screen.redraw());
  }).catch(() => {});

  return {
    get status() {
      return { activity: story.active ? `coffee-${story.phase}` : greeting.active ? "greeting" : lampAction ? "lamp" : routine.activity, greeting: greeting.active, coffee: story.phase, lampOn };
    },
    start() {
      running = true;
      last = performance.now();
      renderer.setAnimationLoop(frame);
    },
    stop() {
      running = false;
      renderer.setAnimationLoop(null);
    },
    render() {
      renderer.render(scene, camera);
    },
    resize,
    setTheme,
    beginWork() {
      if (!state.waiting) return;
      state.waiting = false;
      greeting.request();
    },
    support() { story.support(); dozeAt = Infinity; },
    // For touch screens: one nap after this many seconds of the scene running.
    dozeAfter(seconds) { dozeAt = state.time + seconds; },
    supportHover(inside) { if (running && !state.waiting) story.hover(inside); },
    skipStory() { story.skip(); },
    cancelStory,
    // Renders a deterministic pose for still images. "work" is the first live
    // frame, so the placeholder swaps to the canvas seamlessly; "bench" shows
    // the workflow `at` seconds in. Repeated calls advance the same workflow.
    pose(name, at = 0) {
      if (name === "sleep") {
        state.waiting = false;
        story.hover(true); story.hover(false); story.startNap();
        coffeeMotion.begin(rig.root.position, state.chair.value);
        state.blinkAt = Infinity;
        for (let i = 0; i <= Math.round(at * 60); i += 1) update(1 / 60);
      }
      if (name === "bench") {
        state.waiting = false;
        routine.start();
        state.blinkAt = Infinity;
        for (let i = 0; i <= Math.round(at * 60); i += 1) update(1 / 60);
      }
      if (name === "hello") {
        state.forced = "engaged";
        state.blinkAt = Infinity;
        screens.terminal.reset();
        for (const char of "sayHi") screens.terminal.typeCommand(char);
        screens.terminal.run();
        for (let i = 0; i < 240; i += 1) update(1 / 60);
      }
      renderer.render(scene, camera);
      return anchor();
    },
    dispose() {
      onCoffee?.(null);
      onLighting?.({ level: 0, power: 0, faultA: 0, faultB: 0 });
      renderer.setAnimationLoop(null);
      scene.traverse((object) => {
        object.geometry?.dispose();
        for (const material of [].concat(object.material || [])) {
          material.map?.dispose();
          material.dispose();
        }
      });
      renderer.dispose();
      renderer.forceContextLoss();
    },
  };
}
