import { Quaternion, Vector3 } from "three";
import { BENCH, MEASURE } from "./models.js";
import { createActivity } from "./activity.js";
import { smooth } from "./rig.js";

const UP = new Vector3(0, 1, 0);
const AXIS = new Vector3(0, 1, 0);
const LIFT = [1.2, 2.0];
const JOINTS = [[2.0, 2.4, 2.7, 4.0], [4.0, 4.35, 4.6, 5.8], [5.8, 6.15, 6.4, 7.6]];
const BACK = [7.6, 8.0, 8.7];
const ABORT = 0.65;
// Moving the board: reach and grip, lift, swivel to the other side, set it down.
const CARRY = { grip: 0.75, lift: [0.95, 1.3], turn: [1.3, 2.15], lower: [2.15, 2.55] };
// Held in front of his chest while the chair turns, in the chair's frame.
const CARRIED = new Vector3(0, 0.9, -0.36);
// The free hand rests on the board's left edge while the scope probe is on a pin.
const STEADY = { wrist: new Vector3(-0.118, 0.032, 0.026), fingers: new Vector3(0.62, -0.42, -0.66).normalize() };
// The board's LED lights while it is powered up for testing.
const LED = { off: "#5a2620", on: "#ff5a4a" };
const span = (t, start, end) => smooth((t - start) / (end - start));

class Pose {
  constructor(position = new Vector3(), quaternion = new Quaternion()) {
    this.position = position;
    this.quaternion = quaternion;
  }

  set(from, to, t) {
    this.position.lerpVectors(from.position, to.position, t);
    this.quaternion.slerpQuaternions(from.quaternion, to.quaternion, t);
    return this;
  }

  copy(pose) {
    this.position.copy(pose.position);
    this.quaternion.copy(pose.quaternion);
    return this;
  }

  point(local, out) {
    return out.copy(local).applyQuaternion(this.quaternion).add(this.position);
  }

  apply(object) {
    object.position.copy(this.position);
    object.quaternion.copy(this.quaternion);
  }
}

const aimed = (...parts) => new Quaternion().setFromUnitVectors(AXIS, parts.reduce((sum, [v, k]) => sum.addScaledVector(v, k), new Vector3()).normalize());

// Read the circuit, assemble it, write firmware, then carry the board over to
// measure voltage and signals, and bring it back to the soldering spot.
export function createRoutine({ bench, terminal, screen, onActivity }) {
  const { iron, solder, project, forward, right, mouse, probes, measurement } = bench;
  const activity = createActivity();
  const rest = (object) => new Pose(object.rest.position.clone(), object.rest.quaternion.clone());
  const ironRest = rest(iron);
  const projectRest = rest(project);
  const projectTested = new Pose(measurement.board.position.clone(), measurement.board.quaternion.clone());
  const probeRest = probes.map(rest);
  const probePoses = probeRest.map((pose) => new Pose().copy(pose));
  const joints = project.joints.map(({ point }) => projectRest.point(point, new Vector3()));
  const working = aimed([forward, -0.45], [right, 0.55], [UP, 0.7]);
  const tipAt = (point) => new Pose(point.clone().sub(iron.tip.clone().applyQuaternion(working)), working.clone());
  const ironOn = joints.map((joint) => tipAt(joint.clone().addScaledVector(UP, 0.0015)));
  const ironAbove = joints.map((joint) => tipAt(joint.clone().addScaledVector(UP, 0.03).addScaledVector(forward, -0.004)));
  const ironLifted = tipAt(joints[0].clone().addScaledVector(UP, 0.09).addScaledVector(right, 0.03));
  const feeding = aimed([forward, -0.35], [right, -0.7], [UP, 0.62]);
  const solderOn = joints.map((joint) => new Pose(joint.clone().addScaledVector(right, -0.004).addScaledVector(UP, 0.004), feeding.clone()));
  const solderUp = new Pose(joints[0].clone().addScaledVector(right, -0.01).addScaledVector(UP, 0.035), feeding.clone());
  const solderRest = new Pose(bench.spool.clone(), aimed([forward, -0.5], [right, -0.2], [UP, 0.84]));
  const ironPose = new Pose().copy(ironRest);
  const solderPose = new Pose().copy(solderRest);
  const projectPose = new Pose().copy(projectRest);
  const carried = new Pose();
  const handStarts = [new Vector3(), new Vector3()];
  const dirStarts = [new Vector3(), new Vector3()];
  const v = { a: new Vector3(), b: new Vector3() };
  const out = {
    chair: 0, roll: 0, lean: 0.17, smile: 0.2, typing: false,
    look: new Vector3(), hands: [new Vector3(), new Vector3()],
    dirs: [new Vector3(), new Vector3()], holding: [false, false], smoke: null, follow: null,
  };
  let active = false;
  let aborting = null;
  let entered = false;
  let from = [];
  // Where the board rests: the soldering spot or beside the meter.
  let board = "bench";
  let carry = null;
  let carrying = false;
  let hurry = false;
  const moving = [ironPose, projectPose, ...probePoses];
  const homes = () => [ironRest, board === "bench" ? projectRest : projectTested, ...probeRest];

  function reset() {
    const home = homes();
    moving.forEach((pose, i) => pose.copy(home[i]));
    solder.group.visible = false;
    project.led.color.set(board === "tested" ? LED.on : LED.off);
    project.joints.forEach((joint) => { joint.material.emissiveIntensity = 0; });
  }

  function applyObjects() {
    ironPose.apply(iron.group);
    solderPose.apply(solder.group);
    projectPose.apply(project.group);
    probePoses.forEach((pose, i) => { pose.apply(probes[i].group); probes[i].update(); });
  }

  function grip(pose, local, hand) {
    const dir = out.dirs[hand];
    dir.copy(AXIS).applyQuaternion(pose.quaternion);
    pose.point(local, out.hands[hand]).addScaledVector(dir, 0.045);
    dir.negate();
    out.holding[hand] = true;
  }

  // Both hands hold the board like a tray, palms under its side edges.
  function holdBoard(pose) {
    project.grips.forEach(({ wrist, fingers }, hand) => {
      pose.point(wrist, out.hands[hand]);
      out.dirs[hand].copy(fingers).applyQuaternion(pose.quaternion);
      out.holding[hand] = true;
    });
  }

  function reach(hand, t, duration = 0.9) {
    const u = span(t, 0, duration);
    out.hands[hand].lerpVectors(handStarts[hand], out.hands[hand], u).addScaledVector(UP, 0.045 * Math.sin(u * Math.PI));
    out.dirs[hand].lerpVectors(dirStarts[hand], out.dirs[hand], u).normalize();
  }

  function enter(wrists, dirs) {
    // A carry that finished before an interruption is not repeated.
    if (activity.name === "carry" && board === "tested") activity.next();
    if (activity.name === "return" && board === "bench") activity.next();
    // Large steps for still renders can jump over a carry; put the board in place.
    const needed = ["multimeter", "oscilloscope", "return"].includes(activity.name) ? "tested" : "bench";
    if (board !== needed) {
      board = needed;
      reset();
    }
    handStarts.forEach((point, i) => point.copy(wrists[i]));
    dirStarts.forEach((point, i) => point.copy(dirs[i]));
    if (activity.name === "schematic") terminal.showSchematic();
    if (activity.name === "code") terminal.showCode();
    if (activity.name === "solder") project.joints.forEach((joint) => { joint.blob.visible = false; });
    onActivity?.(activity.name);
    entered = true;
  }

  function placeObjects(t) {
    if (t < LIFT[0]) ironPose.copy(ironRest);
    else if (t < LIFT[1]) ironPose.set(ironRest, ironLifted, span(t, ...LIFT));
    else if (t < BACK[0]) {
      const j = JOINTS.findIndex(([, , , off]) => t < off);
      const [move, above, on] = JOINTS[j];
      if (t < above) ironPose.set(j ? ironOn[j - 1] : ironLifted, ironAbove[j], span(t, move, above));
      else if (t < on) ironPose.set(ironAbove[j], ironOn[j], span(t, above, on));
      else ironPose.copy(ironOn[j]).position.addScaledVector(right, Math.sin(t * 14) * 0.0012);
    } else if (t < BACK[1]) ironPose.set(ironOn[2], ironLifted, span(t, BACK[0], BACK[1]));
    else if (t < BACK[2]) ironPose.set(ironLifted, ironRest, span(t, BACK[1], BACK[2]));
    else ironPose.copy(ironRest);

    if (t < LIFT[1]) solderPose.set(solderRest, solderUp, span(t, ...LIFT));
    else if (t < BACK[0]) {
      const j = JOINTS.findIndex(([, , , off]) => t < off);
      const [move, , on, off] = JOINTS[j];
      if (t < on) solderPose.set(j ? solderOn[j - 1] : solderUp, solderOn[j], span(t, move, on));
      else {
        // Feed the wire into the joint while it melts.
        solderPose.copy(solderOn[j]);
        solderPose.position.addScaledVector(v.a.copy(AXIS).applyQuaternion(feeding), -0.005 * span(t, on, off));
      }
    } else solderPose.set(solderOn[2], solderRest, span(t, BACK[0], BACK[2]));
    solder.group.visible = t > LIFT[0] && t < BACK[2];

    projectPose.copy(projectRest);
  }

  function soldering(t) {
    placeObjects(t);
    out.chair = BENCH.yaw;
    out.roll = BENCH.roll;
    out.lean = BENCH.lean;
    ironPose.point(iron.tip, out.look);
    grip(solderPose, solder.grip, 0);
    grip(ironPose, iron.grip, 1);
    reach(0, t, LIFT[0]);
    reach(1, t, LIFT[0]);
    project.joints.forEach((joint, j) => {
      const [, , on, off] = JOINTS[j];
      const size = span(t, on + 0.1, on + 0.8);
      joint.blob.visible = size > 0.01;
      joint.blob.scale.set(size, size * 0.6, size);
      joint.material.emissiveIntensity = 1.8 * span(t, on, on + 0.3) * (1 - span(t, off - 0.1, off + 0.8));
      if (t > on + 0.15 && t < off) out.smoke = joints[j];
    });
  }

  // Runs once the chair has turned this frame, so the board stays in his hands.
  function follow(rig) {
    const { t, start, end } = carry;
    rig.actor.localToWorld(carried.position.copy(CARRIED));
    rig.actor.getWorldQuaternion(carried.quaternion);
    if (t < CARRY.lift[1]) projectPose.set(start, carried, span(t, ...CARRY.lift));
    else if (t < CARRY.lower[0]) projectPose.copy(carried);
    else projectPose.set(carried, end, span(t, ...CARRY.lower));
    projectPose.apply(project.group);
    holdBoard(projectPose);
  }

  // Picks the board up, turns with it in both hands, and sets it down.
  function moveBoard(t, start, end, seat, destination) {
    carry = { t, start, end };
    const turn = span(t, ...CARRY.turn);
    const other = destination === "tested" ? MEASURE : BENCH;
    out.chair = seat.yaw + (other.yaw - seat.yaw) * turn;
    out.roll = seat.roll + (other.roll - seat.roll) * turn;
    // Bend to pick it up and to set it down; sit up while it is in his hands.
    const upright = seat.lean + (0.22 - seat.lean) * span(t, ...CARRY.lift);
    out.lean = upright + (other.lean + 0.05 - upright) * span(t, ...CARRY.lower);
    carrying = t >= CARRY.lift[0] && t < CARRY.lower[1];
    if (t >= CARRY.lower[1] && board !== destination) board = destination;
    project.led.color.set(board === "tested" && !carrying ? LED.on : LED.off);
    if (carrying) {
      // Last frame's pose until follow() places it against the turned chair.
      out.follow = follow;
      holdBoard(projectPose);
    } else {
      projectPose.copy(t < CARRY.lift[0] ? start : end);
      holdBoard(projectPose);
      if (t < CARRY.lift[0]) {
        reach(0, t, CARRY.grip);
        reach(1, t, CARRY.grip);
      }
    }
    out.look.copy(projectPose.position);
  }

  function measuring(t, scope) {
    const station = bench.measurement;
    out.chair = MEASURE.yaw;
    out.roll = MEASURE.roll;
    out.lean = MEASURE.lean;
    projectPose.copy(projectTested);
    const indices = scope ? [2] : [0, 1];
    for (const i of indices) {
      const home = probeRest[i];
      const pose = probePoses[i];
      const point = station.testPoints[i];
      const direction = new Vector3().addScaledVector(station.forward, -0.35).addScaledVector(station.right, i === 0 ? -0.45 : 0.45).addScaledVector(UP, 0.82).normalize();
      const contact = new Pose(point.clone(), new Quaternion().setFromUnitVectors(AXIS, direction));
      const lifted = new Pose(point.clone().add(v.a.set(0, 0.09, 0.06)), contact.quaternion.clone());
      if (t < 0.9) pose.copy(home);
      else if (t < 1.6) pose.set(home, lifted, span(t, 0.9, 1.6));
      else if (t < 2) pose.set(lifted, contact, span(t, 1.6, 2));
      else if (t < 4.8) pose.copy(contact);
      else if (t < 5.3) pose.set(contact, lifted, span(t, 4.8, 5.3));
      else pose.set(lifted, home, span(t, 5.3, 6.2));
      if (t < 6.2) {
        const hand = scope ? 1 : i;
        grip(pose, probes[i].grip, hand);
        reach(hand, t);
      }
    }
    if (scope) {
      // Keep the board steady with the free hand while touching its signal pin.
      projectTested.point(STEADY.wrist, out.hands[0]);
      out.dirs[0].copy(STEADY.fingers).applyQuaternion(projectTested.quaternion);
      out.holding[0] = t < 5.3;
      reach(0, t);
    }
    out.look.copy(t > 2.6 && t < 4.8 ? (scope ? bench.scopeScreen : bench.meterScreen) : projectTested.position);
    out.smile = t > 3 && t < 4.8 ? 0.7 : 0.2;
  }

  return {
    get active() { return active; },
    get activity() { return activity.name; },
    get time() { return activity.time; },
    start() {
      if (active) return;
      active = true;
      aborting = null;
      entered = false;
      hurry = false;
    },
    // Puts the tools down over `duration` seconds. The board is never dropped
    // mid-carry: the carry hurries instead, and the scene asks again every frame.
    abort(duration = ABORT) {
      if (!active || aborting) return;
      if (carrying) {
        hurry = true;
        return;
      }
      hurry = false;
      aborting = { time: 0, duration, holding: [...out.holding], activity: activity.name };
      from = moving.map((pose) => new Pose().copy(pose));
      solder.group.visible = false;
      out.smoke = null;
      out.follow = null;
      project.joints.forEach((joint) => { joint.material.emissiveIntensity = 0; });
    },
    update(dt, wrists, dirs) {
      if (!active) return null;
      if (aborting) {
        aborting.time += dt;
        const u = span(aborting.time, 0, aborting.duration);
        const home = homes();
        moving.forEach((pose, i) => pose.set(from[i], home[i], u));
        out.typing = false;
        out.smoke = null;
        out.holding = [...aborting.holding];
        if (aborting.activity === "solder") {
          if (out.holding[1]) grip(ironPose, iron.grip, 1);
          out.holding[0] = false;
        } else if (aborting.activity === "multimeter") {
          out.holding.forEach((holding, i) => { if (holding) grip(probePoses[i], probes[i].grip, i); });
        } else if (aborting.activity === "oscilloscope" && out.holding[1]) grip(probePoses[2], probes[2].grip, 1);
        else if (aborting.activity === "carry" || aborting.activity === "return") out.holding = [false, false];
        if (u >= 1) {
          active = false;
          activity.restartStep();
          reset();
          applyObjects();
          return null;
        }
      } else {
        if (!entered) enter(wrists, dirs);
        if (activity.advance(hurry ? dt * 2 : dt)) { reset(); enter(wrists, dirs); }
        const t = activity.time;
        Object.assign(out, { chair: 0, roll: 0, lean: 0.17, smile: 0.2, typing: false, smoke: null, follow: null });
        out.holding = [false, false];
        carrying = false;
        out.look.copy(screen);
        if (activity.name === "schematic") {
          out.hands[1].copy(mouse).add(v.a.set(Math.sin(t * 1.6) * 0.005, 0.02, 0.07));
          out.dirs[1].set(0, -0.3, -1).normalize();
          out.holding[1] = true;
          reach(1, t);
          out.look.add(v.a.set(Math.sin(t * 0.8) * 0.08, Math.cos(t) * 0.04, 0));
        } else if (activity.name === "solder") soldering(t);
        else if (activity.name === "code") out.typing = true;
        else if (activity.name === "carry") moveBoard(t, projectRest, projectTested, BENCH, "tested");
        else if (activity.name === "return") moveBoard(t, projectTested, projectRest, MEASURE, "bench");
        else measuring(t, activity.name === "oscilloscope");
        // Only a carry in progress is hurried, even if the interruption is withdrawn.
        if (!carrying) hurry = false;
      }
      applyObjects();
      return out;
    },
  };
}
