import { Matrix4, Vector3 } from "three";

const axis = new Vector3();
const side = new Vector3();
const front = new Vector3();
const basis = new Matrix4();

// Seeded noise keeps the faceting identical in the live scene and the stills.
export function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
export const mix = (a, b, t) => a + (b - a) * t;
export const smooth = (t) => {
  const x = clamp(t, 0, 1);
  return x * x * (3 - 2 * x);
};
export const damp = (value, target, rate, dt) => value + (target - value) * (1 - Math.exp(-rate * dt));
export const wrapAngle = (angle) => Math.atan2(Math.sin(angle), Math.cos(angle));

// A damped spring gives the chair a little overshoot when it swivels.
export class Spring {
  constructor(value = 0, stiffness = 40, damping = 11) {
    this.value = value;
    this.velocity = 0;
    this.stiffness = stiffness;
    this.damping = damping;
  }

  update(target, dt) {
    const steps = Math.max(1, Math.ceil(dt * 240));
    const h = dt / steps;
    for (let i = 0; i < steps; i += 1) {
      this.velocity += (this.stiffness * (target - this.value) - this.damping * this.velocity) * h;
      this.value += this.velocity * h;
    }
    return this.value;
  }

  set(value) {
    this.value = value;
    this.velocity = 0;
  }
}

// Two-bone IK: places the elbow or knee so both bones keep their length.
export function solveLimb(root, target, pole, upper, lower, joint, end) {
  axis.subVectors(target, root);
  const reach = axis.length();
  axis.divideScalar(reach || 1);
  const distance = clamp(reach, Math.abs(upper - lower) + 1e-3, upper + lower - 1e-3);
  side.subVectors(pole, root);
  side.addScaledVector(axis, -side.dot(axis));
  if (side.lengthSq() < 1e-8) side.set(-axis.y, axis.x, 0);
  side.normalize();
  const along = (upper * upper - lower * lower + distance * distance) / (2 * distance);
  const height = Math.sqrt(Math.max(upper * upper - along * along, 0));
  joint.copy(root).addScaledVector(axis, along).addScaledVector(side, height);
  end.copy(root).addScaledVector(axis, distance);
}

// Points an object's +Y from `from` to `to`, using `hint` to choose its +X.
export function placeSegment(object, from, to, hint) {
  axis.subVectors(to, from).normalize();
  side.copy(hint).addScaledVector(axis, -hint.dot(axis));
  if (side.lengthSq() < 1e-8) side.set(axis.y, -axis.x, 0);
  side.normalize();
  front.crossVectors(side, axis);
  basis.makeBasis(side, axis, front);
  object.quaternion.setFromRotationMatrix(basis);
  object.position.copy(from);
}
