// The board he is building: three header pins to solder along the front edge.
function buildProject(kit) {
  const c = palette;
  const group = new Group();
  kit.box(group, 0.13, 0.006, 0.09, c.pcb, { at: [0, 0.003, 0] });
  kit.box(group, 0.036, 0.007, 0.02, c.chip, { at: [-0.016, 0.0095, -0.014] });
  for (let i = 0; i < 4; i += 1) {
    for (const z of [-0.0265, -0.0015]) kit.box(group, 0.004, 0.004, 0.005, c.steel, { at: [-0.0285 + i * 0.0085, 0.007, z], shadow: false });
  }
  kit.cylinder(group, 0.0038, 0.0038, 0.018, 8, "#d8b48a", { at: [0.034, 0.011, -0.02], rot: [0, 0, Math.PI / 2], shadow: false });
  kit.cylinder(group, 0.006, 0.006, 0.015, 10, c.blue, { at: [-0.046, 0.013, 0.014], shadow: false });
  const led = ledMaterial("#5a2620");
  kit.cylinder(group, 0.0042, 0.0042, 0.008, 8, led, { at: [0.04, 0.011, 0.008], shadow: false });
  kit.ball(group, 0.0042, led, { at: [0.04, 0.0152, 0.008], shadow: false });
  kit.box(group, 0.056, 0.009, 0.01, c.header, { at: [0, 0.0105, 0.03], shadow: false });
  for (const x of [-0.05, 0.05]) kit.cylinder(group, 0.006, 0.006, 0.0015, 12, c.brass, { at: [x, 0.007, -0.027], metal: 0.6, shadow: false });
  const joints = [-0.018, 0, 0.018].map((x) => {
    kit.box(group, 0.002, 0.02, 0.002, c.brass, { at: [x, 0.019, 0.03], metal: 0.5, rough: 0.4, shadow: false });
    kit.cylinder(group, 0.0044, 0.0044, 0.0012, 10, c.brass, { at: [x, 0.0066, 0.041], metal: 0.5, rough: 0.4, shadow: false });
    const material = new MeshStandardMaterial({ color: "#d4d8dc", metalness: 0.7, roughness: 0.25, emissive: "#ff7a2a", emissiveIntensity: 0 });
    const blob = new Mesh(new SphereGeometry(0.0048, 12, 8), material);
    blob.position.set(x, 0.0074, 0.041);
    blob.scale.set(1, 0.6, 1);
    group.add(blob);
    return { point: new Vector3(x, 0.0078, 0.041), blob, material };
  });
  // Carried in both hands like a tray: palms under the side edges, fingers curled in.
  const grips = [-1, 1].map((s) => ({ wrist: new Vector3(s * 0.1, -0.016, 0.03), fingers: new Vector3(-s * 0.5, 0.1, -0.86).normalize() }));
  return { group, joints, led, grips };
}

// The iron's lead, re-laid between the station and the iron as the iron moves.
function buildCable(kit, parent, color = palette.knob) {
  const count = 16;
  const geometry = new CylinderGeometry(0.0045, 0.0045, 1, 5, 1, true);
  geometry.translate(0, 0.5, 0);
  const segments = new InstancedMesh(geometry, kit.material(color), count);
  parent.add(segments);
  const curve = new CatmullRomCurve3([new Vector3(), new Vector3(), new Vector3(), new Vector3()]);
  const points = Array.from({ length: count + 1 }, () => new Vector3());
  const piece = new Object3D();
  const side = new Vector3(1, 0, 0);
  return {
    // An optional desk point the lead passes through, to lie around other things.
    update(start, end, desk, via) {
      const [a, b, c, d] = curve.points;
      a.copy(start);
      d.copy(end);
      if (via) b.copy(via).setY(desk + 0.006);
      else b.lerpVectors(start, end, 0.35).setY(desk + 0.006);
      c.lerpVectors(via || start, end, via ? 0.55 : 0.72).setY(Math.max(desk + 0.012, end.y - 0.07));
      points.forEach((point, i) => curve.getPoint(i / count, point));
      for (let i = 0; i < count; i += 1) {
        placeSegment(piece, points[i], points[i + 1], side);
        piece.scale.set(1, Math.max(points[i].distanceTo(points[i + 1]), 1e-4), 1);
        piece.updateMatrix();
        segments.setMatrixAt(i, piece.matrix);
      }
      segments.instanceMatrix.needsUpdate = true;
      segments.computeBoundingSphere();
    },
  };
}

