function buildLamp(kit, target) {
  const group = new Group();
  const enamel = "#355f59";
  kit.cylinder(group, 0.073, 0.083, 0.025, 20, enamel, { at: [0, 0.0125, 0] });
  const elbow = [-0.045, 0.25, -0.035];
  kit.rod(group, [0, 0.026, 0], elbow, 0.011, palette.metal, { metal: 0.5 });
  const head = new Group();
  // Extend over the soldering area so the open shade faces down at the board.
  head.position.set(0.2, 0.52, 0.34);
  // Shade and spotlight share the actual board target in lamp-local space.
  const aim = target.clone().sub(head.position).normalize();
  head.quaternion.setFromUnitVectors(new Vector3(0, -1, 0), aim);
  group.add(head);
  const joint = new Vector3(0, 0.058, 0).applyQuaternion(head.quaternion).add(head.position);
  kit.rod(group, elbow, joint.toArray(), 0.012, enamel);
  kit.ball(group, 0.023, enamel, { at: elbow });
  kit.ball(group, 0.023, enamel, { at: joint.toArray() });
  kit.mesh(head, new CylinderGeometry(0.045, 0.105, 0.11, 32, 1, true), enamel, { side: DoubleSide });
  kit.mesh(head, new CylinderGeometry(0.04, 0.098, 0.102, 32, 1, true), "#ddd8bb", { side: DoubleSide });
  kit.mesh(head, new TorusGeometry(0.103, 0.005, 6, 24), enamel, { at: [0, -0.055, 0], rot: [Math.PI / 2, 0, 0] });
  const bulb = kit.mesh(head, new SphereGeometry(0.025, 20, 12), "#f9df9c", { at: [0, -0.026, 0], scale: [1, 0.65, 1], basic: true, shadow: false });
  // The switch is on the side of the shade that faces his chair.
  const side = Math.PI / 3;
  const toggle = kit.box(head, 0.019, 0.011, 0.025, palette.knob, { at: [Math.cos(side) * 0.087, -0.027, Math.sin(side) * 0.087], rot: [0, Math.PI - side, Math.PI / 2] });
  toggle.rotation.order = "YXZ";
  const source = new Vector3(0, -0.06, 0).applyQuaternion(head.quaternion).add(head.position);
  return { group, bulb, toggle, source, target };
}

function buildProbe(kit, color, position, jack, parent, top, via) {
  const group = new Group();
  kit.cylinder(group, 0.002, 0.002, 0.025, 8, palette.steel, { at: [0, 0.0125, 0], metal: 0.6 });
  kit.cylinder(group, 0.008, 0.007, 0.075, 10, color, { at: [0, 0.0625, 0] });
  kit.cylinder(group, 0.012, 0.012, 0.005, 10, color, { at: [0, 0.028, 0] });
  group.position.copy(position);
  group.rotation.z = Math.PI / 2;
  parent.add(group);
  bake(group);
  const end = new Vector3(0, 0.104, 0);
  const cable = buildCable(kit, parent, color);
  const tip = new Vector3();
  const update = () => {
    group.updateMatrixWorld(true);
    cable.update(jack, group.localToWorld(tip.copy(end)), top, via);
  };
  update();
  return { group, grip: new Vector3(0, 0.065, 0), update, rest: { position: group.position.clone(), quaternion: group.quaternion.clone() } };
}

function buildPlant(kit) {
  const c = palette;
  const group = new Group();
  kit.cylinder(group, 0.05, 0.038, 0.085, 8, c.pot, { at: [0, 0.0425, 0] });
  kit.cylinder(group, 0.045, 0.045, 0.006, 8, c.coffee, { at: [0, 0.083, 0], shadow: false });
  for (let i = 0; i < 7; i += 1) {
    const angle = (i / 7) * Math.PI * 2;
    const tilt = 0.18 + (i % 3) * 0.08;
    const height = 0.14 + (i % 2) * 0.05;
    kit.mesh(group, new ConeGeometry(0.02, height, 4), i % 2 ? c.leaf : c.leafLight, {
      at: [Math.cos(angle) * 0.018, 0.085 + height / 2, Math.sin(angle) * 0.018],
      rot: [Math.sin(angle) * tilt, angle, -Math.cos(angle) * tilt],
      scale: [1, 1, 0.35],
    });
  }
  return group;
}

// Desk, floor, and the electronics bench around the character.
export function buildWorld(kit, screens) {
  const c = palette;
  const group = new Group();
  const top = 0.74;
  const place = (object, x, z, rotation = 0, y = top) => {
    object.position.set(x, y, z);
    object.rotation.y = rotation;
    group.add(object);
    object.updateMatrixWorld(true);
    return object;
  };
  const world = (object, local) => object.localToWorld(local.clone());

  const floor = new Mesh(new PlaneGeometry(9, 9), new ShadowMaterial({ opacity: 0.16 }));
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  group.add(floor);
  const chairHome = new Vector3(-0.06, 0, 0.8);
  const rug = kit.material(c.rug);
  kit.cylinder(group, 1, 1, 0.01, 14, c.rugBorder, { at: [chairHome.x + 0.05, 0.005, chairHome.z - 0.05], scale: [0.78, 1, 0.62] });
  kit.cylinder(group, 1, 1, 0.012, 14, rug, { at: [chairHome.x + 0.05, 0.007, chairHome.z - 0.05], scale: [0.7, 1, 0.55] });

  const desk = new Group();
  group.add(desk);
  kit.box(desk, 1.72, 0.035, 0.76, c.wood, { at: [0, top - 0.0175, 0] });
  for (const x of [-0.81, 0.81]) {
    for (const z of [-0.33, 0.33]) kit.box(desk, 0.045, top - 0.035, 0.045, c.deskLeg, { at: [x, (top - 0.035) / 2, z] });
    kit.box(desk, 0.035, 0.035, 0.66, c.deskLeg, { at: [x, 0.1, 0] });
  }
  kit.box(desk, 1.58, 0.05, 0.025, c.deskLeg, { at: [0, top - 0.06, -0.33] });
  kit.box(desk, 0.4, 0.5, 0.6, c.woodShade, { at: [-0.57, 0.38, -0.04] });
  for (let i = 0; i < 3; i += 1) {
    kit.box(desk, 0.37, 0.15, 0.012, c.wood, { at: [-0.57, 0.22 + i * 0.16, 0.265] });
    kit.box(desk, 0.07, 0.012, 0.014, c.deskLeg, { at: [-0.57, 0.26 + i * 0.16, 0.277] });
  }

  const monitor = buildMonitor(kit, screens.terminal.texture);
  place(monitor.group, -0.1, -0.13);
  const keyboard = place(buildKeyboard(kit), -0.08, 0.17);
  keyboard.rotation.x = 0.04;
  keyboard.updateMatrixWorld(true);
  const pad = new Group();
  kit.box(pad, 0.2, 0.004, 0.17, c.panel, { at: [0, 0.002, 0] });
  kit.ball(pad, 1, c.beige, { at: [0.01, 0.017, 0.01], scale: [0.031, 0.02, 0.05] });
  place(pad, 0.26, 0.19, -0.1);

  const scope = buildScope(kit, screens.scope.texture);
  place(scope.group, 0.52, -0.16, -0.38);
  const nucleo = buildNucleo(kit);
  place(nucleo.group, 0.3, 0.01, 0.25);
  const bread = buildBreadboard(kit);
  place(bread.group, 0.75, 0.08, -1.2);
  const meter = buildMeter(kit, screens.meter.texture);
  place(meter.group, 0.76, 0.27, -0.65);
  // The soldering spot sits where he can reach it after swivelling left.
  const seat = chairHome.clone().add(new Vector3(0, 0, BENCH.roll));
  const forward = new Vector3(-Math.sin(BENCH.yaw), 0, -Math.cos(BENCH.yaw));
  const right = new Vector3(Math.cos(BENCH.yaw), 0, -Math.sin(BENCH.yaw));
  const spot = (along, across) => seat.clone().addScaledVector(forward, along).addScaledVector(right, across);
  const station = buildStation(kit, screens.station.texture);
  place(station.group, -0.55, -0.17, 0.3);
  const stand = buildIronStand(kit);
  const standSpot = spot(0.6, 0.2);
  place(stand.group, standSpot.x, standSpot.z, BENCH.yaw);
  const project = buildProject(kit);
  const projectSpot = spot(0.55, 0);
  place(project.group, projectSpot.x, projectSpot.z, BENCH.yaw);
  const mug = buildMug(kit);
  place(mug.group, 0.23, 0.31, 0.4);
  const lampBase = new Vector3(-0.75, top, -0.28);
  const lampTarget = project.group.position.clone().add(new Vector3(0, 0.008, 0)).sub(lampBase);
  const lamp = buildLamp(kit, lampTarget);
  place(lamp.group, lampBase.x, lampBase.z);
  place(buildPlant(kit), 0.76, -0.27, 0);
  const spool = new Group();
  kit.cylinder(spool, 0.03, 0.03, 0.006, 12, c.chairDark, { at: [0, 0.003, 0] });
  kit.cylinder(spool, 0.024, 0.024, 0.03, 12, c.steel, { at: [0, 0.021, 0], metal: 0.6, rough: 0.35 });
  kit.cylinder(spool, 0.03, 0.03, 0.006, 12, c.chairDark, { at: [0, 0.039, 0] });
  const spoolSpot = spot(0.75, -0.06);
  place(spool, spoolSpot.x, spoolSpot.z);
  const iron = buildIron(kit);
  const solder = buildSolder(kit);
  for (const part of [iron, solder, project]) bake(part.group, (object) => project.joints.some((joint) => joint.blob === object));
  const lead = new Group();
  group.add(iron.group, solder.group, lead);
  stand.holder.getWorldPosition(iron.group.position);
  stand.holder.getWorldQuaternion(iron.group.quaternion);
  const cable = buildCable(kit, lead);
  // Probe leads: scope to board, meter to the breadboard, station to iron.
  const scopeJack = world(scope.group, scope.probe);
  const [black, red] = meter.jacks.map((jack) => world(meter.body, jack));
  const probes = [
    buildProbe(kit, c.knob, new Vector3(.54, top + .012, .31), black, group, top),
    buildProbe(kit, c.red, new Vector3(.65, top + .012, .28), red, group, top),
    // The scope lead passes left of the board on its way to the front of the desk.
    buildProbe(kit, c.knob, new Vector3(.42, top + .012, .3), scopeJack, group, top, new Vector3(.39, top, .09)),
  ];
  const stationJack = world(station.group, station.jack);
  iron.group.updateMatrixWorld(true);
  cable.update(stationJack, world(iron.group, iron.end), top);

  // He carries the soldered board to this spot in front of the meter to test it.
  const measureSeat = chairHome.clone().add(new Vector3(0, 0, MEASURE.roll));
  const measureForward = new Vector3(-Math.sin(MEASURE.yaw), 0, -Math.cos(MEASURE.yaw));
  const measureRight = new Vector3(Math.cos(MEASURE.yaw), 0, -Math.sin(MEASURE.yaw));
  const tested = new Object3D();
  tested.position.copy(measureSeat).addScaledVector(measureForward, 0.6).addScaledVector(measureRight, 0.1).setY(top);
  tested.rotation.y = MEASURE.yaw;
  tested.updateMatrixWorld(true);
  // Black and red meter probes on the outer header pins, the scope on the middle one.
  const testPoints = [0, 2, 1].map((j) => world(tested, project.joints[j].point.clone().add(new Vector3(0, 0.003, 0))));

  const keys = world(keyboard, new Vector3(0, 0.05, 0.1));
  const movable = [mug.group, lamp.bulb, lamp.toggle, iron.group, solder.group, project.group, lead, ...probes.map((probe) => probe.group)];
  bake(group, (object) => movable.includes(object));
  return {
    group,
    floor,
    rug,
    chairHome,
    coffee: { ...mug, rest: { position: mug.group.position.clone(), quaternion: mug.group.quaternion.clone() } },
    lamp: { ...lamp, source: world(lamp.group, lamp.source), target: world(lamp.group, lamp.target), switch: world(lamp.toggle, new Vector3()) },
    focus: {
      screen: world(monitor.group, monitor.screen),
      scope: world(scope.group, scope.screen),
      meter: world(meter.body, meter.screen),
      board: world(nucleo.group, new Vector3()),
      keys: [world(keyboard, new Vector3(-0.1, 0.05, 0.1)), world(keyboard, new Vector3(0.1, 0.05, 0.1))],
      keyboard: keys,
    },
    leds: [
      { material: nucleo.led, on: "#5dff8a", off: "#1f4a2c", rate: 1 },
      { material: bread.led, on: "#ff5a4a", off: "#5a2620", rate: 2 },
    ],
    steam: world(iron.group, iron.tip),
    bench: {
      seat,
      forward,
      right,
      top,
      iron: { ...iron, rest: { position: iron.group.position.clone(), quaternion: iron.group.quaternion.clone() } },
      solder,
      project: { ...project, rest: { position: project.group.position.clone(), quaternion: project.group.quaternion.clone() } },
      spool: world(spool, new Vector3(0, 0.045, 0)),
      mouse: world(pad, new Vector3(0.01, 0.03, 0.01)),
      stationJack,
      cable,
      probes,
      measurement: {
        forward: measureForward,
        right: measureRight,
        board: { position: tested.position.clone(), quaternion: tested.quaternion.clone() },
        testPoints,
      },
      scopeControl: world(scope.group, new Vector3(0.07, 0.115, 0.12)),
      meterScreen: world(meter.body, meter.screen),
      scopeScreen: world(scope.group, scope.screen),
    },

  };
}
