import { CanvasTexture, SRGBColorSpace } from "three";

const MONO = '"JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace';
const PHOSPHOR = "#a5d5a1";
const SYNTAX = {
  comment: "#5f8f68",
  string: "#e5c07b",
  macro: "#d5ac65",
  keyword: "#82d5bc",
  number: "#d5ac65",
  call: "#d9f0c6",
  text: PHOSPHOR,
};
const TOKENS = /(\/\/.*$)|("[^"]*")|(^#\w+)|\b(int|void|while|if|return|static|const|uint8_t|uint32_t|frame_t)\b|\b(\d+)\b|\b([a-z_]\w*)(?=\()/g;
const KINDS = ["comment", "string", "macro", "keyword", "number", "call"];

// Short programs the character types after the greeting, one file at a time.
const PROGRAMS = [
  ["main.c", `#include "board.h"

int main(void) {
  board_init();
  while (1) {
    led_toggle(LED_AMBER);
    sleep_ms(500);
  }
}`],
  ["frame.c", `// BLE photo frame
void on_write(const uint8_t *buf) {
  frame_t f = decode(buf);
  if (f.ok) epd_draw(&f);
}`],
  ["shell", `$ make -j8 && make flash
  CC   main.c
  LD   firmware.elf
  Flashing... done`],
  ["adc.c", `static int read_mv(void) {
  uint32_t raw = adc_read(CH_VBAT);
  return raw * 3300 / 4095;
}`],
];

function surface(width, height) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.anisotropy = 4;
  return { ctx: canvas.getContext("2d"), texture };
}

function roundRect(ctx, x, y, width, height, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + width, y, x + width, y + height, radius);
  ctx.arcTo(x + width, y + height, x, y + height, radius);
  ctx.arcTo(x, y + height, x, y, radius);
  ctx.arcTo(x, y, x + width, y, radius);
  ctx.closePath();
}

function tokens(line) {
  const parts = [];
  let index = 0;
  for (const match of line.matchAll(TOKENS)) {
    if (match.index > index) parts.push([line.slice(index, match.index), "text"]);
    const kind = KINDS[match.slice(1).findIndex(Boolean)];
    parts.push([match[0], kind]);
    index = match.index + match[0].length;
  }
  if (index < line.length) parts.push([line.slice(index), "text"]);
  return parts;
}

// The retro monitor: a prompt for the intro, then an editor that fills as he types.
export function createTerminal() {
  const width = 512;
  const height = 384;
  const { ctx, texture } = surface(width, height);
  let mode = "prompt";
  let command = "";
  let program = 0;
  let revealed = 0;
  let pause = 0;
  let cursor = true;
  let dirty = true;
  let drawn = 0;

  function background() {
    ctx.fillStyle = "#10261d";
    ctx.fillRect(0, 0, width, height);
    const glow = ctx.createRadialGradient(width / 2, height / 2, 40, width / 2, height / 2, width * 0.7);
    glow.addColorStop(0, "rgba(130, 213, 160, 0.10)");
    glow.addColorStop(1, "rgba(0, 0, 0, 0.35)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, width, height);
  }

  function scanlines() {
    ctx.fillStyle = "rgba(0, 0, 0, 0.16)";
    for (let y = 0; y < height; y += 4) ctx.fillRect(0, y, width, 1);
  }

  function promptGlyph(x, y, size) {
    ctx.strokeStyle = PHOSPHOR;
    ctx.lineWidth = size * 0.11;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    ctx.moveTo(x, y - size * 0.42);
    ctx.lineTo(x + size * 0.3, y - size * 0.18);
    ctx.lineTo(x, y + size * 0.06);
    ctx.moveTo(x + size * 0.42, y + size * 0.1);
    ctx.lineTo(x + size * 0.72, y + size * 0.1);
    ctx.stroke();
  }

  function drawPrompt() {
    const size = 50;
    const top = mode === "hello" ? 112 : 170;
    promptGlyph(46, top, size);
    ctx.font = `${size * 0.82}px ${MONO}`;
    ctx.fillStyle = PHOSPHOR;
    ctx.textBaseline = "alphabetic";
    ctx.fillText(command, 46 + size * 0.95, top + size * 0.1);
    const end = 46 + size * 0.95 + ctx.measureText(command).width + 6;
    if (mode === "prompt" && cursor) ctx.fillRect(end, top - size * 0.48, size * 0.42, size * 0.62);
    if (mode !== "hello") return;
    ctx.fillStyle = "#163326";
    ctx.strokeStyle = "#5c9a6c";
    ctx.lineWidth = 4;
    roundRect(ctx, 40, 170, width - 80, 150, 12);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#c6ecb8";
    ctx.textAlign = "center";
    ctx.font = `bold 64px ${MONO}`;
    ctx.fillText("Hello!", width / 2, 262);
    ctx.font = `20px ${MONO}`;
    ctx.fillStyle = PHOSPHOR;
    ctx.fillText("Welcome to BrightBytes.dev", width / 2, 300);
    ctx.textAlign = "left";
  }

  function drawCode() {
    const [name, source] = PROGRAMS[program];
    ctx.fillStyle = "rgba(165, 213, 161, 0.12)";
    ctx.fillRect(0, 0, width, 34);
    ctx.fillStyle = "#1c3b2e";
    ctx.fillRect(14, 4, 120, 30);
    ctx.font = `16px ${MONO}`;
    ctx.fillStyle = PHOSPHOR;
    ctx.fillText(name, 28, 25);
    const lines = source.slice(0, revealed).split("\n");
    ctx.font = `20px ${MONO}`;
    const lineHeight = 28;
    const top = 70;
    lines.forEach((line, row) => {
      const y = top + row * lineHeight;
      ctx.fillStyle = SYNTAX.comment;
      ctx.fillText(String(row + 1).padStart(2, " "), 14, y);
      let x = 58;
      for (const [text, kind] of tokens(line)) {
        ctx.fillStyle = SYNTAX[kind];
        ctx.fillText(text, x, y);
        x += ctx.measureText(text).width;
      }
      if (row === lines.length - 1 && cursor) {
        ctx.fillStyle = PHOSPHOR;
        ctx.fillRect(x + 2, y - 18, 11, 22);
      }
    });
  }

  // The board he just soldered: MCU, LED with its resistor, decoupling cap, and J1.
  function drawSchematic(time) {
    ctx.fillStyle = "rgba(165, 213, 161, 0.12)";
    ctx.fillRect(0, 0, width, 34);
    ctx.fillStyle = "#1c3b2e";
    ctx.fillRect(14, 4, 170, 30);
    ctx.font = `16px ${MONO}`;
    ctx.fillStyle = PHOSPHOR;
    ctx.fillText("board.kicad_sch", 26, 25);
    ctx.fillStyle = "rgba(165, 213, 161, 0.13)";
    for (let x = 16; x < width; x += 16) for (let y = 48; y < height; y += 16) ctx.fillRect(x, y, 2, 2);
    ctx.lineWidth = 3;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = PHOSPHOR;
    const wire = (...points) => {
      ctx.beginPath();
      points.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
      ctx.stroke();
    };
    const dot = (x, y) => {
      ctx.beginPath();
      ctx.arc(x, y, 5, 0, Math.PI * 2);
      ctx.fillStyle = PHOSPHOR;
      ctx.fill();
    };
    const ground = (x, y) => {
      wire([x - 14, y], [x + 14, y]);
      wire([x - 9, y + 6], [x + 9, y + 6]);
      wire([x - 4, y + 12], [x + 4, y + 12]);
    };
    wire([70, 74], [330, 74]);
    wire([200, 74], [200, 110]);
    wire([86, 74], [86, 182]);
    wire([72, 182], [100, 182]);
    wire([72, 194], [100, 194]);
    wire([86, 194], [86, 300]);
    ground(86, 300);
    dot(86, 74);
    dot(200, 74);
    ctx.strokeStyle = "#c6ecb8";
    ctx.strokeRect(150, 110, 100, 160);
    ctx.strokeStyle = PHOSPHOR;
    for (const y of [140, 172, 204, 236]) {
      wire([132, y], [150, y]);
      wire([250, y], [268, y]);
    }
    wire([200, 270], [200, 300]);
    ground(200, 300);
    wire([268, 140], [300, 140]);
    wire([300, 140], [308, 128], [320, 152], [332, 128], [344, 152], [352, 140]);
    wire([352, 140], [392, 140], [392, 168]);
    ctx.beginPath();
    ctx.moveTo(376, 168);
    ctx.lineTo(408, 168);
    ctx.lineTo(392, 194);
    ctx.closePath();
    ctx.stroke();
    wire([376, 196], [408, 196]);
    wire([414, 172], [428, 160]);
    wire([418, 184], [432, 172]);
    wire([392, 196], [392, 300]);
    ground(392, 300);
    wire([268, 204], [430, 204]);
    wire([268, 236], [430, 236]);
    wire([360, 268], [430, 268]);
    wire([360, 268], [360, 300]);
    ground(360, 300);
    ctx.strokeStyle = "#c6ecb8";
    ctx.strokeRect(430, 190, 40, 92);
    ctx.fillStyle = PHOSPHOR;
    for (const y of [204, 236, 268]) {
      ctx.beginPath();
      ctx.arc(450, y, 5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.font = `15px ${MONO}`;
    ctx.fillStyle = SYNTAX.number;
    ctx.fillText("+3V3", 300, 64);
    ctx.fillText("U1", 152, 102);
    ctx.fillText("C1 100n", 24, 230);
    ctx.fillText("R1 330", 296, 120);
    ctx.fillText("D1", 414, 200);
    ctx.fillText("J1", 432, 182);
    ctx.fillStyle = PHOSPHOR;
    ctx.font = `14px ${MONO}`;
    ctx.fillText("STM32", 174, 196);
    // His mouse pointer drifts across the sheet.
    const x = 300 + Math.sin(time * 0.7) * 110;
    const y = 200 + Math.sin(time * 1.1) * 60;
    ctx.strokeStyle = "#f4d35e";
    ctx.lineWidth = 2;
    wire([x - 12, y], [x + 12, y]);
    wire([x, y - 12], [x, y + 12]);
  }

  function draw(time = 0) {
    background();
    if (mode === "code") drawCode();
    else if (mode === "schematic") drawSchematic(time);
    else drawPrompt();
    scanlines();
    texture.needsUpdate = true;
    dirty = false;
  }

  return {
    texture,
    reset() {
      mode = "prompt";
      command = "";
      dirty = true;
    },
    typeCommand(char) {
      command += char;
      dirty = true;
    },
    run() {
      mode = "hello";
      dirty = true;
    },
    showSchematic() {
      mode = "schematic";
      dirty = true;
    },
    showCode() {
      mode = "code";
      revealed = 0;
      pause = 0;
      dirty = true;
    },
    // Each keystroke reveals one more character of the current file.
    typeCode() {
      if (mode !== "code") {
        mode = "code";
        revealed = 0;
      }
      if (pause > 0) return;
      const source = PROGRAMS[program][1];
      revealed += 1;
      while (source[revealed] === " ") revealed += 1;
      if (revealed >= source.length) pause = 1.6;
      dirty = true;
    },
    update(time, dt) {
      if (pause > 0) {
        pause -= dt;
        if (pause <= 0) {
          program = (program + 1) % PROGRAMS.length;
          revealed = 0;
          dirty = true;
        }
      }
      const blink = Math.floor(time * 2.2) % 2 === 0;
      if (blink !== cursor) {
        cursor = blink;
        dirty = true;
      }
      if (mode === "schematic" && time - drawn > 1 / 15) dirty = true;
      if (dirty) {
        draw(time);
        drawn = time;
      }
    },
    redraw: draw,
  };
}

// Two channels: a sine on CH1 and the blinking LED's square wave on CH2.
export function createScope() {
  const width = 256;
  const height = 168;
  const { ctx, texture } = surface(width, height);
  let last = -1;
  const draw = (time) => {
    ctx.fillStyle = "#0b1611";
    ctx.fillRect(0, 0, width, height);
    ctx.lineWidth = 1;
    ctx.strokeStyle = "rgba(130, 213, 188, 0.16)";
    ctx.beginPath();
    for (let x = 0; x <= width; x += 32) {
      ctx.moveTo(x + 0.5, 0);
      ctx.lineTo(x + 0.5, height);
    }
    for (let y = 4; y <= height; y += 32) {
      ctx.moveTo(0, y + 0.5);
      ctx.lineTo(width, y + 0.5);
    }
    ctx.stroke();
    ctx.lineWidth = 3;
    ctx.shadowBlur = 6;
    ctx.strokeStyle = ctx.shadowColor = "#f4d35e";
    ctx.beginPath();
    for (let x = 0; x <= width; x += 3) {
      const y = 52 + 28 * Math.sin((x / width) * Math.PI * 4 - time * 3) + Math.sin(x * 1.7 + time * 40) * 1.2;
      if (x === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.strokeStyle = ctx.shadowColor = "#6ad8e6";
    ctx.beginPath();
    let previous = null;
    for (let x = 0; x <= width; x += 2) {
      const y = Math.sin((x / width) * Math.PI * 6 - time * 2) > 0 ? 104 : 140;
      if (previous === null) ctx.moveTo(x, y);
      else if (previous !== y) ctx.lineTo(x, previous);
      ctx.lineTo(x, y);
      previous = y;
    }
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.font = `bold 13px ${MONO}`;
    ctx.fillStyle = "#f4d35e";
    ctx.fillText("CH1 1V", 8, 160);
    ctx.fillStyle = "#6ad8e6";
    ctx.fillText("CH2 2V", 80, 160);
    texture.needsUpdate = true;
  };
  return {
    texture,
    update(time) {
      if (time - last < 1 / 24) return;
      last = time;
      draw(time);
    },
    redraw: () => draw(Math.max(last, 0)),
  };
}

export function createMeterDisplay() {
  const width = 160;
  const height = 84;
  const { ctx, texture } = surface(width, height);
  let reading = "3.30";
  let next = 0;
  const draw = () => {
    ctx.fillStyle = "#b9c6a6";
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = "#1d241c";
    ctx.font = `bold 13px ${MONO}`;
    ctx.fillText("DC", 10, 18);
    ctx.font = `bold 50px ${MONO}`;
    ctx.fillText(reading, 8, 70);
    ctx.font = `bold 24px ${MONO}`;
    ctx.fillText("V", 130, 70);
    texture.needsUpdate = true;
  };
  draw();
  return {
    texture,
    update(time) {
      if (time < next) return;
      next = time + 0.9 + ((time * 7.3) % 1);
      reading = ["3.29", "3.30", "3.30", "3.31"][Math.floor(time * 13) % 4];
      draw();
    },
    redraw: draw,
  };
}

export function createStationDisplay() {
  const width = 128;
  const height = 64;
  const { ctx, texture } = surface(width, height);
  const draw = () => {
    ctx.fillStyle = "#140d0b";
    ctx.fillRect(0, 0, width, height);
    ctx.shadowBlur = 8;
    ctx.fillStyle = ctx.shadowColor = "#ff6a3d";
    ctx.font = `bold 40px ${MONO}`;
    ctx.fillText("320", 8, 48);
    ctx.font = `bold 16px ${MONO}`;
    ctx.fillText("°C", 90, 30);
    ctx.shadowBlur = 0;
    texture.needsUpdate = true;
  };
  draw();
  return { texture, redraw: draw };
}

// The T-shirt print: while(1) { ; } over two lines, keyword in the site's teal.
export function createPrint() {
  const { ctx, texture } = surface(1024, 512);
  texture.anisotropy = 8;
  const line = (parts, y) => {
    const width = parts.reduce((sum, [text]) => sum + ctx.measureText(text).width, 0);
    let x = (1024 - width) / 2;
    for (const [text, color] of parts) {
      ctx.fillStyle = color;
      ctx.fillText(text, x, y);
      x += ctx.measureText(text).width;
    }
  };
  const draw = () => {
    ctx.clearRect(0, 0, 1024, 512);
    ctx.font = `bold 174px ${MONO}`;
    line([["while", "#075e57"], ["(1)", "#181c20"]], 216);
    line([["{ ", "#181c20"], [";", "#996015"], [" }", "#181c20"]], 428);
    texture.needsUpdate = true;
  };
  draw();
  return { texture, redraw: draw };
}
