import { Matrix4, Vector3 } from "three";
import { LAMP } from "./models.js";
import { smooth } from "./rig.js";

const span = (t, start, end) => smooth((t - start) / (end - start));
const UP = new Vector3(0, 1, 0);
// The idle hand relaxes on his thigh, in the chair's frame, so it turns with him.
const RESTING = [new Vector3(-0.13, 0.71, -0.33), new Vector3(0.13, 0.71, -0.33)];
const RESTING_DIRS = [new Vector3(0.1, -0.35, -1).normalize(), new Vector3(-0.1, -0.35, -1).normalize()];
// Wrist distance from the switch: hovering, then fingertips on it.
const HOVER = 0.125;
const TOUCH = 0.095;
// Seconds: lift the left hand to the shade, press, then sit back.
export const LAMP_TIMING = { reach: [0.3, 1.0], press: [1.0, 1.22], click: 1.1, back: [1.3, 1.95], end: 2 };

// He leans toward the lamp and flicks the switch on the shade with his left hand.
export function createLampMotion({ world }) {
  const target = world.lamp.switch;
  const starts = [new Vector3(), new Vector3()];
  const startDirs = [new Vector3(), new Vector3()];
  const inverse = new Matrix4();
  const v = { start: new Vector3(), dir: new Vector3(), rest: new Vector3(), restDir: new Vector3(), shoulder: new Vector3(), press: new Vector3(), hover: new Vector3() };
  let time = 0;
  const out = {
    chair: LAMP.yaw, roll: LAMP.roll, lean: LAMP.lean, smile: 0.2, typing: false,
    look: new Vector3(), holding: [true, true],
    hands: [new Vector3(), new Vector3()], dirs: [new Vector3(), new Vector3()],
    follow,
  };

  // Runs once the chair has turned this frame, so both hands move with his body.
  function follow({ actor, shoulders }) {
    const t = time;
    for (const i of [0, 1]) {
      actor.localToWorld(v.start.copy(starts[i]));
      v.dir.copy(startDirs[i]).transformDirection(actor.matrixWorld);
      actor.localToWorld(v.rest.copy(RESTING[i]));
      v.restDir.copy(RESTING_DIRS[i]).transformDirection(actor.matrixWorld);
      const hand = out.hands[i];
      const dir = out.dirs[i];
      if (i === 1) {
        const u = span(t, 0, 0.7);
        hand.lerpVectors(v.start, v.rest, u);
        dir.lerpVectors(v.dir, v.restDir, u).normalize();
        continue;
      }
      // Point the fingers along the reach from his shoulder, a little upward.
      shoulders[0].getWorldPosition(v.shoulder);
      v.press.subVectors(target, v.shoulder).normalize().addScaledVector(UP, 0.15).normalize();
      const press = t > LAMP_TIMING.press[0] && t < LAMP_TIMING.press[1] ? Math.sin(Math.PI * span(t, ...LAMP_TIMING.press)) : 0;
      v.hover.copy(target).addScaledVector(v.press, -(HOVER - (HOVER - TOUCH) * press));
      if (t < LAMP_TIMING.back[0]) {
        const u = span(t, ...LAMP_TIMING.reach);
        hand.lerpVectors(v.start, v.hover, u).addScaledVector(UP, 0.07 * Math.sin(Math.PI * u));
        dir.lerpVectors(v.dir, v.press, u).normalize();
      } else {
        const u = span(t, ...LAMP_TIMING.back);
        hand.lerpVectors(v.hover, v.rest, u).addScaledVector(UP, 0.04 * Math.sin(Math.PI * u));
        dir.lerpVectors(v.press, v.restDir, u).normalize();
      }
    }
  }

  return {
    get time() { return time; },
    begin(actor, wrists, dirs) {
      time = 0;
      actor.updateMatrixWorld(true);
      inverse.copy(actor.matrixWorld).invert();
      starts.forEach((point, i) => point.copy(wrists[i]).applyMatrix4(inverse));
      startDirs.forEach((dir, i) => dir.copy(dirs[i]).transformDirection(inverse));
    },
    update(dt) {
      time += dt;
      // Sit back once the light is switched; work resumes from there.
      out.lean = LAMP.lean + (0.3 - LAMP.lean) * span(time, ...LAMP_TIMING.back);
      out.look.lerpVectors(target, world.focus.screen, span(time, LAMP_TIMING.back[0], LAMP_TIMING.end));
      return out;
    },
  };
}
