// Timed by the scene clock; the left-column interlude needs an unclicked hover,
// or on touch screens, a while spent watching without opening the support link.
export const COFFEE_PHASES = [
  ["sleep", 0.6], ["neon", 8],
  ["wake", 1.5], ["thanks", 2.2], ["return", 1.5],
];

export function createCoffeeStory() {
  let phase = null;
  let time = 0;
  let hovered = false;
  let activated = false;
  let napRequested = false;
  const set = (name) => { phase = name; time = 0; };
  return {
    get active() { return phase !== null; },
    get pending() { return napRequested; },
    get phase() { return phase; },
    get time() { return time; },
    get duration() { return COFFEE_PHASES.find(([name]) => name === phase)?.[1] || 1; },
    get attention() { return phase === "neon"; },
    get covered() { return ["sleep", "neon", "wake"].includes(phase); },
    startNap() {
      if (!napRequested) return false;
      napRequested = false;
      set("sleep");
      return true;
    },
    advance(dt) {
      if (!phase) return;
      time += dt;
      if (time < this.duration) return;
      const next = { sleep: "neon", neon: "wake", thanks: "return", wake: null, return: null };
      set(next[phase]);
    },
    hover(inside) {
      if (inside === hovered) return;
      hovered = inside;
      if (inside) {
        activated = false;
        napRequested = false;
      } else if (!activated) {
        if (["sleep", "neon"].includes(phase)) set("neon");
        else napRequested = true; // The scene puts any tools down first.
      }
    },
    // Touch screens have no hover; the scene asks for one nap on a timer instead.
    doze() {
      if (!phase && !activated) napRequested = true;
    },
    support() {
      // Opening the link acknowledges interest, never a completed payment.
      activated = true;
      napRequested = false;
      if (phase) set("thanks");
    },
    skip() { hovered = false; napRequested = false; if (phase) set("wake"); },
    cancel() {
      hovered = false;
      activated = false;
      napRequested = false;
      phase = null;
    },
  };
}
