import { Vector3 } from "three";
import { smooth } from "./rig.js";
import { COFFEE_PHASES } from "./coffeeStory.js";

// He nods off within the sleep phase, so the neon follows the support key quickly.
const FALL = COFFEE_PHASES.find(([name]) => name === "sleep")[1];

// A user-triggered nap stays seated, facing the desk with hands on the bench.
export function createCoffeeMotion({ world }) {
  const seat = world.chairHome.clone();
  let yaw = 0;
  let wakingFrom = 0;
  let lastPhase = null;
  let fromLean = 0.17;
  const fromLook = new Vector3();
  const fromHands = world.focus.keys.map((hand) => hand.clone());
  const fromDirs = [new Vector3(), new Vector3()];
  const restingHands = [new Vector3(), new Vector3()];
  const restingDirs = [new Vector3(), new Vector3()];
  const restingLook = new Vector3();
  const forward = new Vector3();
  const right = new Vector3();
  const out = {
    chair: 0, roll: 0, lean: 0.17, smile: 0.2, typing: false, sleep: 0,
    look: world.focus.screen.clone(), holding: [true, true],
    hands: world.focus.keys.map((hand) => hand.clone()),
    dirs: [new Vector3(0, -0.7, -0.2).normalize(), new Vector3(0, -0.7, -0.2).normalize()],
  };
  return {
    begin(position, chairYaw, pose = {}) {
      seat.copy(position); yaw = chairYaw; out.chair = chairYaw; lastPhase = null;
      out.sleep = 0;
      out.lean = pose.lean ?? .17;
      out.look.copy(pose.look || world.focus.screen);
      forward.set(-Math.sin(yaw), 0, -Math.cos(yaw));
      right.set(Math.cos(yaw), 0, -Math.sin(yaw));
      restingLook.copy(seat).addScaledVector(forward, .55).setY(world.focus.keyboard.y);
      out.hands.forEach((hand, i) => {
        const side = i ? 1 : -1;
        hand.copy(pose.hands?.[i] || world.focus.keys[i]);
        out.dirs[i].copy(pose.dirs?.[i] || forward);
        restingHands[i].copy(seat).addScaledVector(forward, .48).addScaledVector(right, side * .14);
        restingHands[i].z -= .11;
        restingHands[i].y = (world.bench?.top ?? .74) + .045;
        // Palms lie flat, with separated wrists and relaxed inward fingers.
        restingDirs[i].copy(forward).addScaledVector(right, -side * .28).normalize();
      });
    },
    update(story) {
      const phase = story.phase;
      if (phase !== lastPhase) {
        wakingFrom = out.sleep;
        fromLean = out.lean;
        fromLook.copy(out.look);
        fromHands.forEach((hand, i) => hand.copy(out.hands[i]));
        fromDirs.forEach((dir, i) => dir.copy(out.dirs[i]));
      }
      lastPhase = phase;
      const u = smooth(story.time / (phase === "sleep" ? FALL : 1.2));
      let sleep = 0;
      if (phase === "sleep") sleep = u;
      if (phase === "neon") sleep = 1;
      if (["wake", "return", "thanks"].includes(phase)) sleep = wakingFrom * (1 - smooth(story.time / 1.2));
      Object.assign(out, { chair: yaw, roll: seat.z - world.chairHome.z - sleep * 0.11, lean: 0.17 + sleep * 0.7, smile: phase === "thanks" ? 0.8 : 0.2, sleep });
      out.look.lerpVectors(world.focus.screen, restingLook, sleep);
      out.hands.forEach((hand, i) => {
        hand.copy(world.focus.keys[i]);
        hand.y += 0.006;
        hand.lerp(restingHands[i], sleep);
        out.dirs[i].copy(forward).lerp(restingDirs[i], sleep).normalize();
      });
      if (phase === "sleep") {
        out.look.lerpVectors(fromLook, restingLook, u);
        out.hands.forEach((hand, i) => hand.lerpVectors(fromHands[i], hand, u));
        out.dirs.forEach((dir, i) => dir.lerpVectors(fromDirs[i], dir, u).normalize());
      } else if (["wake", "return", "thanks"].includes(phase)) {
        out.lean = fromLean + (0.17 - fromLean) * u;
        out.look.lerpVectors(fromLook, world.focus.screen, u);
        out.hands.forEach((hand, i) => hand.lerpVectors(fromHands[i], hand, u));
        out.dirs.forEach((dir, i) => dir.lerpVectors(fromDirs[i], dir, u).normalize());
      }
      return out;
    },
  };
}
