import { BufferAttribute, BufferGeometry, Color, DynamicDrawUsage, Points, ShaderMaterial } from "three";

// Soft round puffs for coffee steam and solder smoke, all drawn in one call.
export function createHaze(count, random) {
  const geometry = new BufferGeometry();
  const attribute = (size) => new BufferAttribute(new Float32Array(count * size), size).setUsage(DynamicDrawUsage);
  const position = attribute(3);
  const size = attribute(1);
  const alpha = attribute(1);
  const tint = attribute(1);
  geometry.setAttribute("position", position);
  geometry.setAttribute("size", size);
  geometry.setAttribute("alpha", alpha);
  geometry.setAttribute("tint", tint);
  const material = new ShaderMaterial({
    uniforms: { steam: { value: new Color() }, smoke: { value: new Color() }, scale: { value: 1 } },
    vertexShader: `
      attribute float size;
      attribute float alpha;
      attribute float tint;
      uniform float scale;
      varying float vAlpha;
      varying float vTint;
      void main() {
        vAlpha = alpha;
        vTint = tint;
        vec4 view = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = size * scale / -view.z;
        gl_Position = projectionMatrix * view;
      }`,
    fragmentShader: `
      uniform vec3 steam;
      uniform vec3 smoke;
      varying float vAlpha;
      varying float vTint;
      void main() {
        float edge = length(gl_PointCoord - 0.5) * 2.0;
        float a = vAlpha * (1.0 - smoothstep(0.3, 1.0, edge));
        if (a < 0.004) discard;
        gl_FragColor = vec4(mix(steam, smoke, vTint), a);
        #include <colorspace_fragment>
      }`,
    transparent: true,
    depthWrite: false,
  });
  const points = new Points(geometry, material);
  points.frustumCulled = false;
  const puffs = Array.from({ length: count }, () => ({ alive: false }));
  let next = 0;

  return {
    points,
    // `rise` and `wind` are metres travelled over the puff's life; sizes are in metres.
    emit(origin, { life, rise, start, grow, peak, shade = 0, spread = 0, wind = [0, 0] }) {
      const puff = puffs[next];
      next = (next + 1) % count;
      Object.assign(puff, {
        alive: true, age: 0, life, rise, start, grow, peak, shade, wind,
        x: origin.x + (random() - 0.5) * spread,
        y: origin.y,
        z: origin.z + (random() - 0.5) * spread,
        drift: random() * Math.PI * 2,
      });
    },
    update(dt) {
      puffs.forEach((puff, i) => {
        if (puff.alive) {
          puff.age += dt;
          puff.alive = puff.age < puff.life;
        }
        if (!puff.alive) {
          size.array[i] = 0;
          alpha.array[i] = 0;
          return;
        }
        const t = puff.age / puff.life;
        // Warm air lifts each puff quickly, then it lingers, spreads, and fades.
        const lift = 1 - (1 - t) * (1 - t);
        position.setXYZ(i,
          puff.x + Math.sin(puff.drift + t * 4) * 0.016 * t + puff.wind[0] * t * t,
          puff.y + puff.rise * lift,
          puff.z + Math.cos(puff.drift + t * 3) * 0.013 * t + puff.wind[1] * t * t);
        size.array[i] = puff.start + puff.grow * t;
        alpha.array[i] = puff.peak * Math.min(1, t * 6) * (1 - t) ** 0.9;
        tint.array[i] = puff.shade;
      });
      position.needsUpdate = true;
      size.needsUpdate = true;
      alpha.needsUpdate = true;
      tint.needsUpdate = true;
    },
    colors(steam, smoke) {
      material.uniforms.steam.value.set(steam);
      material.uniforms.smoke.value.set(smoke);
    },
    // Pixels per metre at unit depth, so puffs keep their size as the canvas changes.
    scale(value) {
      material.uniforms.scale.value = value;
    },
  };
}
