import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/addons/libs/meshopt_decoder.module.js";

let template;
let loading;
const controls = ["AhmadHead", "EyeLeft", "EyeRight", "BrowLeft", "BrowRight", "MouthNeutral", "MouthSmile"];

// The authored head is independent of the body, outfit and workbench rig.
// Cache the source but give every mounted scene its own disposable resources.
export function loadPortrait(url = "/animations/ahmad-head.glb", buffer) {
  if (template) return Promise.resolve();
  if (!loading) {
    const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
    loading = (buffer ? loader.parseAsync(buffer, "") : loader.loadAsync(url))
      .then(({ scene }) => {
        for (const name of controls) {
          if (!scene.getObjectByName(name)) throw new Error(`Portrait is missing ${name}`);
        }
        template = scene.getObjectByName("AhmadHead");
      })
      .catch((error) => { loading = undefined; throw error; });
  }
  return loading;
}

export function buildHead() {
  if (!template) throw new Error("Load the portrait before building the character");
  const head = template.clone(true);
  const geometries = new Map(), materials = new Map();
  const copyMaterial = (material) => {
    if (!materials.has(material)) materials.set(material, material.clone());
    return materials.get(material);
  };
  head.traverse((object) => {
    if (!object.isMesh) return;
    if (!geometries.has(object.geometry)) geometries.set(object.geometry, object.geometry.clone());
    object.geometry = geometries.get(object.geometry);
    object.material = Array.isArray(object.material) ? object.material.map(copyMaterial) : copyMaterial(object.material);
    object.castShadow = object.userData.castShadow !== false;
    object.receiveShadow = object.userData.receiveShadow !== false;
  });
  head.rotation.order = "YXZ";
  const get = (name) => head.getObjectByName(name);
  const mouth = { line: get("MouthNeutral"), grin: get("MouthSmile") };
  mouth.line.visible = true;
  mouth.grin.visible = false;
  return {
    head,
    eyes: [get("EyeLeft"), get("EyeRight")],
    brows: [get("BrowLeft"), get("BrowRight")],
    mouth,
  };
}
